-- ── البلاغات الخمسة ──
UPDATE questions SET explanation = 'الجملة تشبّه العقبات بالحجارة: لا تتعثر بها بل اجمعها وابنِ منها سلّمًا تصعد به نحو النجاح.<br>الفعلان «اجمعها» و«ابنِ بها» يناسبان الحجارة وحدها، والسلّم يُصعد عليه، فالإجابة: بالحجارة – تصعد.' WHERE id = 'f0c63d5c-6eb5-4e1f-a95b-3f97ca65fa0f';
UPDATE reports SET status = 'resolved', admin_notes = 'أُصلح: الشرح كان يعرض رمز السطر الجديد حرفياً — أعيدت صياغته. السؤال والإجابة صحيحان.', resolved_at = now(),
  resolved_by = (SELECT id FROM profiles WHERE email = 'abodi2040@gmail.com') WHERE question_id = 'f0c63d5c-6eb5-4e1f-a95b-3f97ca65fa0f' AND status = 'pending';
UPDATE questions SET question_text = 'ينطبق مبدأ برنولي على المائع:', choices = '["الساكن", "المتدفق بانتظام", "المتدفق دون انتظام", "المضطرب"]'::jsonb WHERE id = '41afcdf4-a588-4103-b944-ff56254825bf';
UPDATE reports SET status = 'resolved', admin_notes = 'أُصلح: نص السؤال كان مقطوعاً (ينطبق مبد) وبقيته داخل الخيار الأول — أعيد النص كاملاً وصار الخيار الأول «الساكن».', resolved_at = now(),
  resolved_by = (SELECT id FROM profiles WHERE email = 'abodi2040@gmail.com') WHERE question_id = '41afcdf4-a588-4103-b944-ff56254825bf' AND status = 'pending';
UPDATE questions SET question_text = 'آلة تطبع 50 صفحة في 20 دقيقة. كم صفحة تطبع في 4 ساعات؟', explanation = '4 ساعات = 240 دقيقة، أي 12 مرة × 20 دقيقة، فعدد الصفحات = 12 × 50 = 600 صفحة.<br>أو بالمعدل: 50 ÷ 20 = 2.5 صفحة في الدقيقة، و2.5 × 240 = 600.' WHERE id = '5582356f-6b5c-4267-830f-68e0000b19fb';
UPDATE reports SET status = 'resolved', admin_notes = 'أُصلح: الرقم 50 سقط من بداية السؤال — أعيد النص كاملاً ووُضّح الشرح.', resolved_at = now(),
  resolved_by = (SELECT id FROM profiles WHERE email = 'abodi2040@gmail.com') WHERE question_id = '5582356f-6b5c-4267-830f-68e0000b19fb' AND status = 'pending';
UPDATE questions SET question_text = 'مثلث طول قاعدته 10 سم وارتفاعه 6 سم، فما مساحته؟', explanation = 'مساحة المثلث = ½ × القاعدة × الارتفاع = ½ × 10 × 6 = 30 سم².<br>لاحظ أن المثلث نصف المستطيل الذي له القاعدة والارتفاع نفسهما: 10 × 6 = 60، ونصفها 30.' WHERE id = 'c17def8d-7745-44b4-a924-7a06e57e3799';
UPDATE reports SET status = 'resolved', admin_notes = 'روجع: السؤال والإجابة صحيحان — أعيدت صياغة النص بوضوح وبُسّط الشرح.', resolved_at = now(),
  resolved_by = (SELECT id FROM profiles WHERE email = 'abodi2040@gmail.com') WHERE question_id = 'c17def8d-7745-44b4-a924-7a06e57e3799' AND status = 'pending';
