DO $chk$
DECLARE n_lig INT; n_bs INT; n_rep INT;
BEGIN
  SELECT COUNT(*) INTO n_lig FROM questions WHERE question_text ~ '(األ|اإل|اآل)' OR choices::text ~ '(األ|اإل|اآل)' OR explanation ~ '(األ|اإل|اآل)';
  SELECT COUNT(*) INTO n_bs FROM questions WHERE strpos(coalesce(explanation,''), chr(92)||'n') > 0;
  SELECT COUNT(*) INTO n_rep FROM reports WHERE status = 'pending';
  RAISE NOTICE 'بقايا الحروف: % — \n حرفية: % — بلاغات معلقة: %', n_lig, n_bs, n_rep;
  IF n_rep <> 0 THEN RAISE EXCEPTION 'بقيت بلاغات معلقة: %', n_rep; END IF;
END
$chk$;

COMMIT;